mapper.select:
SELECT bt.id, bt.user_id AS userId, u.username AS username, bt.type, bt.amount, bt.hold_amount AS holdAmount, bt.balance_after AS balanceAfter, bt.frozen_after AS frozenAfter, bt.biz_key AS bizKey, bt.task_id AS taskId, bt.ref_order_no AS refOrderNo, bt.operator_id AS operatorId, bt.operator_name AS operatorName, bt.coupon_id AS couponId, bt.remark, bt.create_time AS createTime FROM balance_transaction bt LEFT JOIN app_user u ON u.id = bt.user_id
AND bt.user_id = #{userId}
AND bt.type = #{type}
ORDER BY bt.create_time DESC, bt.id DESC

SELECT bt.id, bt.user_id AS userId, bt.type, bt.amount, bt.hold_amount AS holdAmount, bt.balance_after AS balanceAfter, bt.frozen_after AS frozenAfter, bt.biz_key AS bizKey, bt.task_id AS taskId, bt.ref_order_no AS refOrderNo, bt.operator_id AS operatorId, bt.operator_name AS operatorName, bt.coupon_id AS couponId, bt.remark, bt.create_time AS createTime FROM balance_transaction bt WHERE bt.user_id = #{userId}
AND bt.type = #{type}
ORDER BY bt.create_time DESC, bt.id DESC
